"""Produce the complete review gallery, footprint/triangle manifest and source provenance."""
from pathlib import Path
from PIL import Image,ImageDraw
import json,html,gzip,struct
import numpy as np
root=Path.cwd();out=root/'TestResults/ArtPass';source=root/'ArtSource/SyntheticFront'
catalog=json.loads((root/'Assets/MassiveArmy/Resources/MassiveArmy/RtsCatalog.json').read_text())
rows=json.loads((source/'geometry-report.json').read_text());bykey={r['kind']+'-'+r['id']:r for r in rows}
items=[(kind,d) for kind in ['building','unit'] for d in catalog[kind+'s']]
cards=[]
for i,(kind,d) in enumerate(items):
 key=kind+'-'+d['id'];r=bykey[key];bespoke=key=='building-command' and (root/'ArtSource/HQ/building-command.mesh.gz').exists()
 if bespoke:
  hq=json.loads((root/'ArtSource/HQ/geometry-report.json').read_text());r.update(triangles=hq['triangles'],vertices=hq['vertices'],width=hq['boundsMetres'][0],height=hq['boundsMetres'][1],depth=hq['boundsMetres'][2],source='ArtSource/HQ/CommandCentre.blend',prototypeNoDecimation=True);r['farTriangles']=hq['triangles']
  data=gzip.decompress((root/'ArtSource/HQ/building-command.mesh.gz').read_bytes());assert data[:4]==b'HQM1';vertices=np.frombuffer(data[8:],dtype='<f4').reshape(-1,16);assert len(vertices)==struct.unpack('<I',data[4:8])[0];assert np.isfinite(vertices).all() and (vertices[:,10:12]>=0).all() and (vertices[:,10:12]<=1).all()
 else:
  payload=json.loads((source/(key+'.json')).read_text());low=json.loads((source/(key+'-lod1.json')).read_text());r['farTriangles']=len(low['vertices'])//3
 if kind=='building':r['tiles']=[d['footprintWidth'],d['footprintDepth']];r['reservedMetres']=[d['footprintWidth']*8,d['footprintDepth']*8]
 assert r['triangles']<=512 if kind=='unit' else True
 assert r['farTriangles']<=128 if kind=='unit' else bespoke or r['farTriangles']<=256
 if not bespoke:
  for v in payload['vertices']:assert 0<=v['uv'][0]<=1.00001 and 0<=v['uv'][1]<=1.00001
 cards.append(f'<article><h2>{html.escape(d["name"])}</h2><img src="../../Assets/MassiveArmy/Resources/MassiveArmy/UI/Portraits/{key}.png"><img src="../../TestResults/ArtPass/Gallery/{key}.png"><p>{r["triangles"]} / {r["farTriangles"]} triangles; '+(str(r['tiles'])+' tiles' if kind=='building' else 'GPU rendered')+'</p></article>')
for page in range(3):
 subset=items[page*30:(page+1)*30];sheet=Image.new('RGB',(1800,((len(subset)+5)//6)*280),(7,15,24));draw=ImageDraw.Draw(sheet)
 for j,(kind,d) in enumerate(subset):
  key=kind+'-'+d['id'];x=(j%6)*300;y=(j//6)*280;im=Image.open(out/'Gallery'/(key+'.png')).convert('RGBA');im.thumbnail((285,245));sheet.paste(im,(x+(300-im.width)//2,y),im);draw.text((x+8,y+247),d['name'],fill=(105,220,246));draw.text((x+8,y+264),f'{bykey[key]["triangles"]} triangles',fill=(150,169,189))
 sheet.save(out/f'models-{page}.png')
doc='<!doctype html><meta charset="utf-8"><title>Synthetic Front model review</title><style>body{background:#07121d;color:#ade4ee;font:16px sans-serif;margin:24px}main{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}article{background:#10212f;padding:12px;border:1px solid #286d82}img{width:48%;background:#06111b}h2{font-size:18px}</style><h1>Synthetic Front: all 80 models</h1><p>UI portrait at left, authored game shell at right. Ground pivot; X/Z dimensions in metres.</p><main>'+''.join(cards)+'</main>'
(source/'manifest.json').write_text(json.dumps(rows,indent=2));(root/'Documentation/3D_ART').mkdir(exist_ok=True);(root/'Documentation/3D_ART/gallery.html').write_text(doc)
(source/'metal-source-prompt.txt').write_text('Original generated texture source. Built-in imagegen, 2026-10-11.\nProduction game albedo texture, seamless square tile, flat orthographic surface scan of brushed titanium and dark gunmetal, fine micro scratches and subtle grain. No baked lighting, shadows, objects, logos or cyan glow. Uniform metal surface suitable as reusable UV texture detail.\nFinal model maps are UV-island palette bakes with this image supplying micro-grain; maps and meshes are generated by the project scripts.\n')
print('Validated and reviewed manifest for',len(rows),'models')
